import { unstable_noStore as noStore } from 'next/cache';

export default function Home() {
  // Log page view without blocking the response
  noStore();

  // Simulate analytics logging that runs after response
  const logPageView = async () => {
    try {
      // This would be your actual analytics service call
      // For example: await fetch('/api/analytics', { method: 'POST', body: JSON.stringify({ page: 'home' }) });
      console.log('Page view logged to analytics service');
    } catch (error) {
      console.error('Failed to log page view:', error);
    }
  };

  // Schedule the logging to run after the response is sent
  logPageView();

  return (
    <main>
      <h1>Welcome</h1>
      <p>Page view has been logged to analytics service.</p>
    </main>
  );
}

